:root {
    --color-primary: #111111;
    --color-primary-hover: #333333;
    --color-secondary: #f0f0f0;
    --color-secondary-hover: #e0e0e0;
    --color-text: #222222;
    --color-text-light: #555555;
    --color-bg: #ffffff;
    --color-bg-alt: #f9f9f9;
    --color-sale: #d93025;
    --color-border: #e5e5e5;
    --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --focus-ring: 0 0 0 3px rgba(0, 123, 255, 0.5);
    --focus-outline: 2px solid #005fcc;
    --transition-speed: 0.2s;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    color: var(--color-text);
    background-color: var(--color-bg);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    color: var(--color-primary);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

/* Focus styles for accessibility */
*:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 2px;
}

/* Screen reader only utility class */
.sr-only:not(:focus):not(:active) {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

/* Skip link styling when focused */
.sr-only:focus {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background: var(--color-primary);
    color: white;
    padding: 0.5rem 1rem;
    z-index: 1000;
    border-radius: 4px;
    text-decoration: none;
}

/* Typography */
h1, h2, h3, h4 {
    line-height: 1.2;
    margin-bottom: 0.5rem;
}

h1 { font-size: 2.5rem; font-weight: 700; }
h2 { font-size: 1.75rem; font-weight: 600; }
h3 { font-size: 1.25rem; font-weight: 500; }

p { margin-bottom: 1rem; }

/* Layout Containers */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1rem;
}

.section {
    padding: 4rem 0;
}

.section-alt {
    background-color: var(--color-bg-alt);
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 1rem;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    font-weight: 500;
    text-align: center;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
    text-decoration: none;
    transition: background-color var(--transition-speed) ease;
}

.btn:hover {
    text-decoration: none;
}

.btn-primary {
    background-color: var(--color-primary);
    color: white;
}

.btn-primary:hover {
    background-color: var(--color-primary-hover);
}

.btn-secondary {
    background-color: var(--color-secondary);
    color: var(--color-text);
}

.btn-secondary:hover {
    background-color: var(--color-secondary-hover);
}

.btn-outline {
    background-color: transparent;
    border: 2px solid var(--color-primary);
    color: var(--color-primary);
}

.btn-outline:hover {
    background-color: var(--color-primary);
    color: white;
}

.btn-icon {
    background: transparent;
    padding: 0.5rem;
    color: var(--color-text);
    border-radius: 50%;
}

.btn-icon:hover {
    background-color: var(--color-secondary);
}

/* Header */
.site-header {
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    background-color: rgba(255, 255, 255, 0.95);
    z-index: 100;
}

.header-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
}

.primary-nav ul {
    list-style: none;
    display: flex;
    gap: 1.5rem;
}

.primary-nav a {
    font-weight: 500;
    color: var(--color-text-light);
}

.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
    color: var(--color-primary);
}

/* Hero Section */
.hero {
    background-color: var(--color-bg-alt);
    padding: 6rem 1rem;
    text-align: center;
}

.hero-content {
    max-width: 600px;
    margin: 0 auto;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--color-text-light);
    margin-bottom: 2rem;
}

/* Product Grid */
.product-grid {
    list-style: none;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    position: relative;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.product-image {
    background-color: var(--color-secondary);
    aspect-ratio: 4/5;
    overflow: hidden;
    margin-bottom: 1rem;
    border-radius: 4px;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-title {
    font-size: 1rem;
    margin-bottom: 0.25rem;
}

/* Ensure the link inside the title spans nicely but doesn't overlap the button */
.product-title a {
    color: inherit;
    text-decoration: none;
}

.product-title a:hover {
    text-decoration: underline;
}

.product-price {
    font-weight: 500;
    color: var(--color-text-light);
    margin-bottom: 1rem;
}

.price-original {
    color: var(--color-text-light);
    margin-right: 0.5rem;
}

.price-sale {
    color: var(--color-sale);
}

.badge-sale {
    position: absolute;
    top: 10px;
    left: 10px;
    background-color: var(--color-sale);
    color: white;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.25rem 0.5rem;
    border-radius: 2px;
    z-index: 1;
}

.add-to-cart {
    margin-top: auto;
    width: 100%;
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    border-radius: 4px;
    overflow: hidden;
    background-color: var(--color-bg-alt);
    height: 100%;
    display: flex;
    flex-direction: column;
}

.editorial-image {
    aspect-ratio: 3/2;
    object-fit: cover;
    width: 100%;
}

.editorial-content {
    padding: 2rem;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.editorial-content h3 {
    margin-bottom: 1rem;
}

.editorial-content p {
    color: var(--color-text-light);
    margin-bottom: 1.5rem;
    flex-grow: 1;
}

/* Footer */
.site-footer {
    background-color: var(--color-bg-alt);
    border-top: 1px solid var(--color-border);
    padding: 4rem 0 2rem;
    margin-top: 4rem;
}

.footer-inner {
    display: grid;
    grid-template-columns: 1fr;
    gap: 3rem;
    margin-bottom: 3rem;
}

@media (min-width: 768px) {
    .footer-inner {
        grid-template-columns: 1fr 2fr;
    }
}

.footer-brand p {
    color: var(--color-text-light);
    margin-top: 1rem;
    max-width: 250px;
}

.footer-nav {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 2rem;
}

.footer-heading {
    font-size: 1rem;
    margin-bottom: 1rem;
}

.footer-nav ul {
    list-style: none;
}

.footer-nav li {
    margin-bottom: 0.5rem;
}

.footer-nav a {
    color: var(--color-text-light);
}

.footer-nav a:hover {
    color: var(--color-primary);
}

.footer-bottom {
    border-top: 1px solid var(--color-border);
    padding-top: 2rem;
    text-align: center;
    color: var(--color-text-light);
    font-size: 0.875rem;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
