            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
        }, null, 2));

        if (wcag.length > 0) {
            process.exit(1);
        }
    } catch (e) {
        console.error("Error:", e);
        process.exit(2);
    }
})();
